def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    threat_bids = []
    urgent_opp = False

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                mult = 1.0
                if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                    mult = 1.08
                    urgent_opp = True
                if opp.get('budget', 0) < DAILY_SALARY * 1.2:
                    mult *= 0.92
                threat_bids.append(float(bid) * mult)

    if not alive:
        return float(min(budget, 18.0))

    alive_count = len(alive)
    plentiful = supply >= 22
    tight = supply <= 17
    very_tight = supply <= 16

    if threat_bids:
        est_top = max(threat_bids)
        est_avg = sum(prev_bids) / max(1, len(prev_bids))
    else:
        est_top = DAILY_SALARY * 0.65
        est_avg = DAILY_SALARY * 0.55

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2
    if very_tight:
        danger += 2
    elif tight:
        danger += 1
    if day >= 8:
        danger += 1

    if plentiful and danger <= 1:
        base = 16.0 + 1.5 * alive_count
    elif plentiful:
        base = 24.0 + 2.0 * danger
    elif tight:
        base = max(32.0 + 4.0 * danger, est_avg * 0.72)
    else:
        base = max(26.0 + 3.0 * danger, est_avg * 0.62)

    if danger >= 5:
        target = max(base, est_top + 2.5)
    elif danger >= 3:
        target = max(base, est_top * 0.9 + 1.5)
    else:
        target = base

    if not urgent_opp and plentiful and hp > 4:
        target = min(target, est_top * 0.72 if threat_bids else target)

    if day == 1 and hp >= 8 and supply >= 20:
        target = min(target, 24.0)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = DAILY_SALARY * 1.2
    if hp <= 3 or no_water >= 1:
        reserve_floor = DAILY_SALARY * 0.4

    cap = budget - reserve_floor
    if cap < 0:
        cap = budget * 0.6
    if hp <= 2 or no_water >= 2:
        cap = budget

    bid = min(budget, max(0.0, min(target, cap)))

    if bid < 1.0 and budget >= 1.0:
        bid = 1.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append((oid, o))

    # If no opponents, just ensure survival.
    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday trace bids for immediate pressure.
    prev_bids = []
    prev_max_bid = 0.0
    prev_min_bid = None
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            b = float(prev['bid'])
            prev_bids.append(b)
            if b > prev_max_bid:
                prev_max_bid = b
            if prev_min_bid is None or b < prev_min_bid:
                prev_min_bid = b

    # Estimate how many water units are likely available.
    # (We don't know exact auction mechanics; use supply to decide urgency.)
    # If supply is low relative to our requirement, we must bid more.
    supply_ratio = supply / float(WATER_REQ)  # e.g., 15/9=1.67

    # Base bid: aim to beat the likely aggressive player without going all-in.
    # Use yesterday's max bid as a proxy for market clearing pressure.
    if prev_bids:
        # If someone already bid very high, we increase but not to full parity.
        if prev_max_bid >= DAILY_SALARY * 1.25:
            target = prev_max_bid * 0.92
        elif prev_max_bid >= DAILY_SALARY * 0.9:
            target = max(DAILY_SALARY * 0.65, prev_max_bid * 0.85)
        else:
            target = max(DAILY_SALARY * 0.55, prev_max_bid + 2.0)
    else:
        target = DAILY_SALARY * 0.55

    # Adjust for our urgency.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        target *= 1.25
    elif my_hp >= 6.0 and my_no_water_days == 0:
        target *= 0.85

    # Adjust for supply conditions.
    # Lower supply => higher chance we need to secure water.
    if supply_ratio < 1.2:
        target *= 1.25
    elif supply_ratio > 1.8:
        target *= 0.9

    # Clamp to feasible budget.
    # Also avoid irrationally high bids: keep within a fraction of budget and a soft cap.
    soft_cap = min(my_budget, DAILY_SALARY * 1.6)
    bid = min(target, soft_cap)

    # Ensure non-negative and at least a small bid if budget allows.
    if bid < 0.0:
        bid = 0.0
    min_reasonable = min(my_budget, DAILY_SALARY * 0.2)
    if bid < min_reasonable and my_budget > 0:
        bid = min_reasonable

    # Final safety: cannot exceed budget.
    bid = min(bid, my_budget)
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
