    DAILY_SALARY = 150
    EPISODE_DAYS = 10 # From meta-round state

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid low to save budget, but ensure water.
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Collect yesterday's bids from active opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Critical survival logic: If HP is very low, bid very aggressively
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents were very aggressive yesterday (e.g., Alex)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3: # If I have healthy HP, try to conserve a bit
                return min(my_status['budget'], DAILY_SALARY * 0.4)
            else: # If HP is low but not critical (handled above if <=2), still need to be aggressive
                return min(my_status['budget'], DAILY_SALARY * 0.95)
        else:
            # If highest bid was moderate or low, try to win for slightly more
            return min(my_status['budget'], max(DAILY_SALARY * 0.55, highest_prev_bid + 2))

    # If no previous bids from alive opponents (e.g., Day 1 or all previous bidders died/didn't bid)
    return min(my_status['budget'], DAILY_SALARY * 0.55)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Look at yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.7
    if yesterday_bids:
        avg_high = sum(sorted(yesterday_bids, reverse=True)[:max(1, len(yesterday_bids)//2)]) / max(1, len(yesterday_bids)//2)
        base_bid = avg_high + 1.0  # slightly above average high

    # Supply adjustment: if supply is high, we can bid lower
    supply_factor = supply / 25.0  # 0.6 to 1.0
    if supply_factor > 0.85:
        base_bid *= 0.9

    # Urgency based on HP
    if hp <= 3:
        urgency = 1.3
    elif hp <= 5:
        urgency = 1.1
    else:
        urgency = 0.95

    bid = min(budget, base_bid * urgency)
    bid = max(bid, 1.0)  # minimum positive bid
    return round(bid, 2)
